import{f as e,o as s,c as n,a2 as o}from"./chunks/framework.Cd9rfTEn.js";const m=JSON.parse('{"title":"CoopApps — La API","description":"","frontmatter":{},"headers":[],"relativePath":"presentacion-stakeholders/api-para-imagenes.md","filePath":"presentacion-stakeholders/api-para-imagenes.md","lastUpdated":null}'),r={name:"presentacion-stakeholders/api-para-imagenes.md"};function t(i,a,l,p,c,d){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="coopapps-—-la-api" tabindex="-1">CoopApps — La API <a class="header-anchor" href="#coopapps-—-la-api" aria-label="Permalink to &quot;CoopApps — La API&quot;">​</a></h1><p>Tres imágenes dedicadas a la API del sistema: cuántas operaciones tiene y para quién, qué reglas cumplen todas, y cómo la cooperativa abre sus datos a terceros de forma controlada. Todos los datos salen de la especificación y de los contratos OpenAPI; ninguno promete algo que no esté escrito.</p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Fecha</td><td>10-11-2026</td></tr><tr><td>Fuentes</td><td><code>docs/entregables-analisis-diseno/18-contratos-api.md</code> (4.193 operaciones, 170 documentos OpenAPI, 1.069 esquemas, convenciones), <code>18-swagger/specs/goodapps-api-completa.json</code> (conteo por superficie y por método), <code>docs/especificacion/anexos/T10-BIA-reportes-bi-apis.md</code> (API para terceros <code>/api/v1/ext</code>, RF-BIA-070 a RF-BIA-084, RN-BIA-031 y RN-BIA-035), <code>T08</code> (RNF-NFR-002, RNF-NFR-007, RNF-NFR-019, RNF-NFR-020)</td></tr><tr><td>Datos</td><td>Todos los nombres de ejemplo son ficticios</td></tr></tbody></table><hr><h2 id="_0-como-usar-este-documento" tabindex="-1">0. Cómo usar este documento <a class="header-anchor" href="#_0-como-usar-este-documento" aria-label="Permalink to &quot;0. Cómo usar este documento&quot;">​</a></h2><ol><li>Si la conversación es nueva, pegar primero el prompt de la sección 0.1.</li><li>Pedir las imágenes por código: &quot;Generá IMG-AP01&quot;, &quot;Generá IMG-AP02&quot; y &quot;Generá IMG-AP03&quot;.</li><li>Cada imagen trae una <strong>frase para decir</strong> en voz alta mientras se muestra.</li></ol><h3 id="_0-1-prompt-de-estilo-pegar-primero" tabindex="-1">0.1 Prompt de estilo (pegar primero) <a class="header-anchor" href="#_0-1-prompt-de-estilo-pegar-primero" aria-label="Permalink to &quot;0.1 Prompt de estilo (pegar primero)&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vas a dibujar tres diapositivas sobre la API de un sistema para cooperativas de servicios públicos de Argentina. El público mezcla directivos y técnicos: cada imagen tiene que entenderse sin saber programar, y a la vez no decir nada que un técnico pueda objetar.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>El tono es seguro y sereno: el de alguien que ya hizo el trabajo y lo muestra. Nada de adjetivos vacíos (&quot;revolucionario&quot;, &quot;potente&quot;, &quot;ilimitado&quot;, &quot;de última generación&quot;), nada de signos de exclamación, nada de lenguaje publicitario.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reglas obligatorias:</span></span>
<span class="line"><span>1. Usá SOLO los textos y números del documento. No inventes cifras, rutas ni nombres. Podés acortar sin cambiar el sentido.</span></span>
<span class="line"><span>2. Texto visible en español de Argentina. Los términos técnicos (OpenAPI, OAuth, webhook) se dejan como están, siempre con su explicación corta al lado.</span></span>
<span class="line"><span>3. Generá cada imagen con código (HTML con SVG en Claude; Python con matplotlib en ChatGPT), 1920×1080 px. No uses el generador de imágenes para nada que tenga texto.</span></span>
<span class="line"><span>4. Paleta: gris carbón #2F343A, gris medio #6B7280, gris claro #E5E7EB, blanco #FFFFFF y verde cooperativo #2E7D32 como único acento. Ámbar #B7791F solo donde el documento lo indique. Sin rojo.</span></span>
<span class="line"><span>5. Composición limpia: mucho espacio en blanco, un título grande (64 a 80 px), un elemento dominante y como máximo cinco elementos de apoyo. Texto mínimo de 20 px.</span></span>
<span class="line"><span>6. Tipografía sans serif limpia (Inter o similar), con peso fuerte en títulos y cifras. Si aparece una ruta, en tipografía monoespaciada.</span></span>
<span class="line"><span>7. Íconos de línea simples. Nada de engranajes brillantes, robots ni efectos futuristas.</span></span>
<span class="line"><span>8. Después de cada imagen, listá qué datos del documento usaste.</span></span>
<span class="line"><span>Esperá mi pedido por código (IMG-AP01 a IMG-AP03).</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><hr><h2 id="_1-las-tres-ideas" tabindex="-1">1. Las tres ideas <a class="header-anchor" href="#_1-las-tres-ideas" aria-label="Permalink to &quot;1. Las tres ideas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Código</th><th>Título de la imagen</th><th>Idea que deja</th></tr></thead><tbody><tr><td>IMG-AP01</td><td>4.193 operaciones, todas con contrato.</td><td>La API está escrita entera antes de programar, y cada operación tiene su ficha</td></tr><tr><td>IMG-AP02</td><td>Las mismas reglas en cada operación.</td><td>Permisos, errores, duplicados y concurrencia se resuelven igual en todo el sistema</td></tr><tr><td>IMG-AP03</td><td>Los datos de la cooperativa, abiertos con llave.</td><td>Terceros pueden usar los datos, solo con permiso, con límites y con registro</td></tr></tbody></table><hr><h2 id="_2-fichas-y-prompts" tabindex="-1">2. Fichas y prompts <a class="header-anchor" href="#_2-fichas-y-prompts" aria-label="Permalink to &quot;2. Fichas y prompts&quot;">​</a></h2><h3 id="img-ap01-—-4-193-operaciones-todas-con-contrato" tabindex="-1">IMG-AP01 — 4.193 operaciones, todas con contrato. <a class="header-anchor" href="#img-ap01-—-4-193-operaciones-todas-con-contrato" aria-label="Permalink to &quot;IMG-AP01 — 4.193 operaciones, todas con contrato.&quot;">​</a></h3><p><strong>Respaldo (<code>18-contratos-api.md</code> y <code>goodapps-api-completa.json</code>):</strong></p><ul><li>La API tiene <strong>4.193 operaciones</strong> (cada combinación de método y ruta), definidas en <strong>170 documentos OpenAPI 3.1</strong>, el estándar para describir APIs, con <strong>1.069 esquemas</strong> de datos. Cubren los 29 módulos con API.</li><li>Todas validan contra el estándar y ninguna ruta se repite.</li><li>Para quién es cada operación:</li></ul><table tabindex="0"><thead><tr><th>Superficie</th><th>Operaciones</th><th>Quién la usa</th></tr></thead><tbody><tr><td>Gestión</td><td>3.399</td><td>El personal de la cooperativa desde la aplicación de gestión</td></tr><tr><td>Plataforma</td><td>198</td><td>El equipo de GoodApps que opera la plataforma</td></tr><tr><td>API para terceros</td><td>106</td><td>Sistemas autorizados por la cooperativa (BI, municipio, federación)</td></tr><tr><td>Públicas</td><td>85</td><td>Landing y trámites sin iniciar sesión</td></tr><tr><td>Portal, app del socio y otras</td><td>405</td><td>Socios, app de campo, acceso y comunicaciones</td></tr></tbody></table><ul><li>Por tipo: 1.584 consultas, 1.923 altas y acciones, 406 modificaciones parciales, 111 reemplazos y 169 bajas.</li><li>Cada operación tiene su ficha en lenguaje de negocio: qué hace, qué requisito cumple, quién la usa, qué recibe, qué devuelve y qué pantallas la usan. Hay un visor Swagger que se abre con doble clic, sin servidor ni internet.</li></ul><p><strong>Frase para decir:</strong> &quot;Antes de escribir una línea de código, ya está definida cada operación del sistema: qué recibe, qué devuelve y quién puede usarla.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-AP01 con código.</span></span>
<span class="line"><span>Título grande: &quot;4.193 operaciones, todas con contrato.&quot;</span></span>
<span class="line"><span>Composición: a la izquierda, el número &quot;4.193&quot; enorme en verde con el rótulo &quot;operaciones de API, descriptas en 170 documentos OpenAPI 3.1&quot;. Debajo, dos cifras menores en gris carbón: &quot;1.069 esquemas de datos&quot; · &quot;29 módulos&quot;.</span></span>
<span class="line"><span>A la derecha, una barra horizontal apilada a todo el ancho, dividida en cinco tramos proporcionales con su cifra y rótulo:</span></span>
<span class="line"><span>&quot;Gestión 3.399&quot; (verde, el tramo dominante) · &quot;Portal, app del socio y otras 405&quot; · &quot;Plataforma 198&quot; · &quot;API para terceros 106&quot; · &quot;Públicas 85&quot; (estos cuatro en grises distintos).</span></span>
<span class="line"><span>Debajo de la barra, una tarjeta tipo ficha ficticia, sobria: &quot;Qué hace · Qué requisito cumple · Quién la usa · Qué recibe · Qué devuelve · Qué pantallas la usan&quot;.</span></span>
<span class="line"><span>Pie: &quot;Validadas contra el estándar · Ninguna ruta repetida · Visor que se abre sin servidor ni internet&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="img-ap02-—-las-mismas-reglas-en-cada-operacion" tabindex="-1">IMG-AP02 — Las mismas reglas en cada operación. <a class="header-anchor" href="#img-ap02-—-las-mismas-reglas-en-cada-operacion" aria-label="Permalink to &quot;IMG-AP02 — Las mismas reglas en cada operación.&quot;">​</a></h3><p><strong>Respaldo (<code>18-contratos-api.md</code> §Convenciones; T08):</strong></p><ul><li><strong>Permiso en cada operación:</strong> el 100 % de las operaciones declara qué permiso exige; las públicas están marcadas como tales.</li><li><strong>La cooperativa sale de la sesión, nunca del pedido:</strong> el dato de a qué cooperativa pertenece cada operación no viaja en lo que se envía, lo pone la sesión del usuario.</li><li><strong>Errores iguales en todo el sistema:</strong> un solo formato estándar de error, con código, explicación, el campo que falló y un número de seguimiento para soporte.</li><li><strong>Repetir no duplica:</strong> toda escritura acepta una clave de idempotencia; si el pedido se repite por un corte de conexión, se aplica una sola vez.</li><li><strong>Nadie pisa el trabajo de otro:</strong> para modificar un registro hay que indicar su versión; si otro lo cambió antes, se avisa en lugar de sobrescribir.</li><li><strong>Listados con tope:</strong> como máximo 100 filas por página; la meta es responder en 0,4 segundos o menos en el 95 % de los casos.</li><li><strong>Lo pesado va en segundo plano:</strong> las operaciones largas responden &quot;aceptado&quot; con un número de seguimiento, y toda exportación de más de 10.000 filas es asíncrona.</li><li><strong>Cuotas por cooperativa:</strong> 600 pedidos por minuto por usuario y 6.000 por cooperativa por defecto; superarlas devuelve &quot;esperá y reintentá&quot;, sin afectar a las demás.</li></ul><p><strong>Frase para decir:</strong> &quot;No hay 4.193 formas de hacer las cosas. Hay una sola, y se aplica igual en cada operación.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-AP02 con código.</span></span>
<span class="line"><span>Título grande: &quot;Las mismas reglas en cada operación.&quot;</span></span>
<span class="line"><span>Composición: una cuadrícula de 4 × 2 tarjetas iguales, cada una con ícono de línea, la regla en negrita y una frase corta en gris:</span></span>
<span class="line"><span>&quot;Permiso declarado&quot; — &quot;El 100 % de las operaciones dice qué permiso exige&quot; ·</span></span>
<span class="line"><span>&quot;La cooperativa la pone la sesión&quot; — &quot;Nunca viaja en el pedido&quot; ·</span></span>
<span class="line"><span>&quot;Un solo formato de error&quot; — &quot;Con código, campo y número de seguimiento&quot; ·</span></span>
<span class="line"><span>&quot;Repetir no duplica&quot; — &quot;Un pedido repetido se aplica una sola vez&quot; ·</span></span>
<span class="line"><span>&quot;Nadie pisa a nadie&quot; — &quot;Se modifica indicando la versión&quot; ·</span></span>
<span class="line"><span>&quot;Listados con tope&quot; — &quot;Hasta 100 filas por página, en 0,4 s&quot; ·</span></span>
<span class="line"><span>&quot;Lo pesado, en segundo plano&quot; — &quot;Más de 10.000 filas, siempre asíncrono&quot; ·</span></span>
<span class="line"><span>&quot;Cuotas por cooperativa&quot; — &quot;Lo que hace una no frena a las demás&quot;.</span></span>
<span class="line"><span>Las tarjetas con borde gris claro y el ícono en verde.</span></span>
<span class="line"><span>Pie: &quot;Una sola forma de hacer las cosas, en las 4.193 operaciones&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="img-ap03-—-los-datos-de-la-cooperativa-abiertos-con-llave" tabindex="-1">IMG-AP03 — Los datos de la cooperativa, abiertos con llave. <a class="header-anchor" href="#img-ap03-—-los-datos-de-la-cooperativa-abiertos-con-llave" aria-label="Permalink to &quot;IMG-AP03 — Los datos de la cooperativa, abiertos con llave.&quot;">​</a></h3><p><strong>Respaldo (T10 §5 y §11.2.6; T08 RNF-NFR-019):</strong> la API para terceros (<code>/api/v1/ext</code>) permite que la cooperativa conecte su propio BI, el municipio, una federación o sus sistemas, con estas condiciones:</p><ul><li><strong>Cliente registrado:</strong> cada sistema externo se da de alta por cooperativa, con responsable, finalidad, contacto técnico, vigencia y restricciones (por ejemplo, por sucursal o por servicio).</li><li><strong>Credenciales estándar:</strong> OAuth 2.0 (credenciales de cliente) o, para herramientas de BI, una clave de solo lectura que no puede escribir.</li><li><strong>Mínimo privilegio:</strong> cada cliente tiene permisos por recurso y acción. Sin el permiso de datos personales, el documento de una persona sale enmascarado. Los permisos de escritura y de datos personales requieren aprobación y finalidad declarada.</li><li><strong>Límites:</strong> por defecto 60 pedidos por minuto y 50.000 registros por día por cliente, ajustables por plan; la meta es responder en 0,8 segundos o menos por página de hasta 1.000 registros, sin afectar el cobro en caja.</li><li><strong>Extracción incremental:</strong> el tercero trae solo lo que cambió desde la última vez; las exportaciones masivas son asíncronas y vencen.</li><li><strong>Avisos salientes firmados</strong> (webhooks): el sistema avisa que algo pasó, sin datos personales en el aviso; el tercero pide el detalle con sus permisos.</li><li><strong>Versiones estables:</strong> los cambios en la versión 1 solo agregan; lo que se retira se anuncia con anticipación.</li><li><strong>Registro de cada llamada:</strong> quién, qué, cuándo, con qué resultado y cuántas filas, sin guardar claves ni tokens.</li><li><strong>Documentación por cooperativa:</strong> cada una ve en su portal de documentación solo los recursos que tiene contratados, con ejemplos ficticios.</li><li>Se construye en la ola O11.</li></ul><p><strong>Frase para decir:</strong> &quot;Los datos son de la cooperativa, y la cooperativa decide quién los usa. Cada sistema externo entra con su llave, ve solo lo que se le permite y deja registro de todo.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-AP03 con código.</span></span>
<span class="line"><span>Título grande: &quot;Los datos de la cooperativa, abiertos con llave.&quot;</span></span>
<span class="line"><span>Composición: en el centro, un bloque verde &quot;Datos de la Cooperativa A&quot; con una cerradura de línea al frente. A la izquierda, tres tarjetas grises de sistemas externos: &quot;BI propio&quot;, &quot;Municipio&quot;, &quot;Federación&quot;; cada una con una llave pequeña y una flecha hacia la cerradura con el rótulo &quot;/api/v1/ext&quot; en tipografía monoespaciada.</span></span>
<span class="line"><span>A la derecha, una columna de cinco condiciones con tilde verde:</span></span>
<span class="line"><span>&quot;Cliente registrado con responsable y finalidad&quot; ·</span></span>
<span class="line"><span>&quot;Solo ve lo que se le permite; datos personales enmascarados sin permiso&quot; ·</span></span>
<span class="line"><span>&quot;60 pedidos por minuto y 50.000 registros por día por defecto&quot; ·</span></span>
<span class="line"><span>&quot;Trae solo lo que cambió&quot; ·</span></span>
<span class="line"><span>&quot;Cada llamada queda registrada&quot;.</span></span>
<span class="line"><span>Abajo, una franja gris claro: &quot;Avisos salientes firmados, sin datos personales · Versiones estables con aviso antes de retirar algo&quot;.</span></span>
<span class="line"><span>Pie: &quot;La cooperativa decide quién usa sus datos&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><hr><h2 id="_3-notas-para-el-presentador" tabindex="-1">3. Notas para el presentador <a class="header-anchor" href="#_3-notas-para-el-presentador" aria-label="Permalink to &quot;3. Notas para el presentador&quot;">​</a></h2><ul><li><strong>Dónde va.</strong> IMG-AP01 después de IMG-E02 (&quot;Está todo escrito.&quot;) en una reunión general, o al abrir el bloque técnico. IMG-AP03 se complementa con IMG-E11 (&quot;Los datos son de la cooperativa.&quot;).</li><li><strong>Si se puede, mostrar el visor en vivo.</strong> El visor Swagger (<code>docs/entregables-analisis-diseno/18-swagger/index.html</code>) se abre con doble clic y permite recorrer cualquier operación. &quot;Probar&quot; está deshabilitado porque todavía no hay sistema detrás; aclararlo antes de que alguien lo intente.</li><li><strong>Puntos a validar en IMG-AP03.</strong> La autenticación de terceros (PA-BIA-02) y el esquema de permisos por campo (PA-BIA-14) están marcados &quot;A validar&quot;; la imagen muestra lo previsto, sin presentarlo como cerrado.</li><li><strong>Los 29 módulos con API</strong> son M01 a M19 y los transversales T01 a T04 y T06 a T11. T05 (modelo de datos) y T12 (fichas de servicios) no exponen API propia.</li><li><strong>&quot;Gestión 3.399&quot;</strong> incluye todas las pantallas del personal. No hace falta explicar la división técnica de rutas; alcanza con decir para quién es cada superficie.</li></ul>`,33)])])}const b=e(r,[["render",t]]);export{m as __pageData,b as default};
